<?php
namespace App\Services\Marketplace\PriceSync;
use App\Models\MarketplaceListing;
class EbayDePriceSyncAdapter implements MarketplacePriceSyncAdapter { public function sync(MarketplaceListing $listing, array $price): array { $type = $this->classify($listing)['type']; if ($type === 'legacy') return ['status'=>'skipped','blocker'=>'ebay_legacy_price_sync_not_supported','final_success'=>false]; return ['status'=>'blocked','blocker'=>'ebay_inventory_price_only_endpoint_not_enabled_quantity_guard','endpoint'=>'/sell/inventory/v1/offer/{offerId}','read_after_write_endpoint'=>'GET /sell/inventory/v1/offer/{offerId}','final_success'=>false]; } public function classify(MarketplaceListing $l): array { $sku = $l->sku ?: data_get($l->raw_payload,'sku'); $inv = $l->external_inventory_id ?: data_get($l->raw_payload,'inventory_item_group_key'); return ($l->marketplace === 'ebay_de' && filled($l->external_offer_id) && filled($sku) && filled($inv)) ? ['type'=>'inventory_api','sku'=>$sku,'inventory_id'=>$inv,'price_only_write_supported'=>false,'quantity_mutation_risk'=>true] : ['type'=>'legacy','sku'=>$sku,'inventory_id'=>$inv,'price_only_write_supported'=>false,'quantity_mutation_risk'=>true]; } }
